 'as_of_date',to_char($1::date,'YYYY-MM-DD'),
 'campaigns',coalesce((SELECT jsonb_agg(c ORDER BY c.id) FROM (SELECT id,name,channel,daily_budget,status,owner_role,owner_slack_id FROM public.mk_campaigns ORDER BY id LIMIT 201)c),'[]'::jsonb),
 'metrics',coalesce((SELECT jsonb_agg(m ORDER BY m.date,m.system,m.campaign_id) FROM (SELECT date,system,campaign_id,spend,clicks,conversions,leads,untagged_leads FROM public.mk_daily_metrics WHERE date BETWEEN $1::date-29 AND $1::date ORDER BY date,system,campaign_id LIMIT 5001)m),'[]'::jsonb),
 'changes',coalesce((SELECT jsonb_agg(c ORDER BY c.date,c.id) FROM (SELECT date,system,campaign_id,change_description FROM public.mk_change_log WHERE date BETWEEN $1::date-29 AND $1::date ORDER BY date,id LIMIT 1001)c),'[]'::jsonb)
) AS snapshot;

