const CONFIG={baselineDays:14,minBaselineDays:10,crmFormRatio:0.70,formAdRatio:0.70,criticalCrmFormRatio:0.40,criticalFormAdRatio:0.40,spendMultiplier:2.5,criticalSpendMultiplier:3.5,budgetMultiplier:1.20,criticalBudgetMultiplier:2,nearZeroConversions:1,conversionFraction:0.10,minimumBaselineConversions:5,normalLow:0.70,normalHigh:1.30,untaggedFraction:0.15,criticalUntaggedFraction:0.30,maxCampaigns:200,maxMetrics:5000,maxChanges:1000,maxFindings:25};
