WITH input AS MATERIALIZED (
 SELECT $1::date AS date,$2::text AS execution_id,$3::text AS ts,$4::text AS channel
), marked AS (
 UPDATE public.mk_findings f SET status='reported',delivery_state='sent',slack_message_ts=i.ts,reported_at=now(),updated_at=now()
 FROM input i WHERE f.row_kind='report' AND f.as_of_date=i.date AND f.execution_id=i.execution_id AND f.delivery_state='sending' AND f.status='open' AND i.ts ~ '^[0-9]+[.][0-9]+$' AND i.channel='<YOUR_SLACK_CHANNEL_ID>'
 RETURNING f.as_of_date
), details AS (
 UPDATE public.mk_findings f SET status='reported',reported_at=now(),updated_at=now() FROM marked m
 WHERE f.as_of_date=m.as_of_date AND f.row_kind='finding' AND f.status='open' RETURNING f.finding_key
)
SELECT 1/(CASE WHEN (SELECT count(*) FROM marked)=1 THEN 1 ELSE 0 END) AS confirmed,(SELECT count(*) FROM details) AS findings_reported;
